import { getSupabase } from "./supabase";
import bundled from "@/data/mass-churches.json";

/**
 * Mass schedules ("Jadwal Misa"). The data is the app's — public.mass_churches,
 * schema PriskatCFM/supabase/068_mass_schedules.sql.
 *
 * It is **bundled** into the site from that table's seed
 * (src/data/mass-churches.json, regenerated by scripts/build-mass-data.mjs), so
 * every page here works with no database connection. If Supabase IS configured
 * it wins — a live table is fresher than a baked snapshot — otherwise the
 * bundle is the source. Either way the shapes below are identical.
 *
 * Structure is province → regency → church, because that's how the table is
 * indexed and how people search ("jadwal misa Surabaya", "misa katedral Jakarta").
 */
export type MassSlot = {
  title: string;
  times: string[];
  is_special?: boolean;
};

export type SpecialSlot = {
  title: string;
  date: string | null;
  times: string[];
};

export type Church = {
  id: number;
  name: string;
  slug: string;
  address: string | null;
  maps_url: string | null;
  province_slug: string;
  province_name: string;
  regency_slug: string;
  regency_name: string;
  schedules: MassSlot[];
  special_schedules: SpecialSlot[];
  synced_at: string | null;
};

export type Province = { slug: string; name: string; churches: number };

export type Regency = {
  slug: string;
  name: string;
  churches: Pick<Church, "slug" | "name" | "address">[];
};

const BUNDLE = bundled as unknown as Church[];

const LIST_COLUMNS =
  "id,name,slug,address,maps_url,province_slug,province_name,regency_slug,regency_name,schedules,special_schedules,synced_at";

/** Pull the whole table from Supabase, or `null` if it isn't configured / errors. */
async function fromSupabase(): Promise<Church[] | null> {
  const supabase = getSupabase();
  if (!supabase) return null;
  const { data, error } = await supabase.from("mass_churches").select(LIST_COLUMNS);
  if (error) {
    console.error("[mass] Supabase read failed, using bundle:", error.message);
    return null;
  }
  return (data ?? []) as unknown as Church[];
}

async function all(): Promise<Church[]> {
  return (await fromSupabase()) ?? BUNDLE;
}

export async function getProvinces(): Promise<Province[]> {
  const byslug = new Map<string, Province>();
  for (const c of await all()) {
    const found = byslug.get(c.province_slug);
    if (found) found.churches += 1;
    else
      byslug.set(c.province_slug, {
        slug: c.province_slug,
        name: c.province_name,
        churches: 1,
      });
  }
  return [...byslug.values()].sort((a, b) => a.name.localeCompare(b.name, "id"));
}

export async function getProvince(
  provinceSlug: string,
): Promise<{ name: string; regencies: Regency[] } | null> {
  const rows = (await all())
    .filter((c) => c.province_slug === provinceSlug)
    .sort(
      (a, b) =>
        a.regency_name.localeCompare(b.regency_name, "id") ||
        a.name.localeCompare(b.name, "id"),
    );
  if (rows.length === 0) return null;

  const byRegency = new Map<string, Regency>();
  for (const c of rows) {
    let regency = byRegency.get(c.regency_slug);
    if (!regency) {
      regency = { slug: c.regency_slug, name: c.regency_name, churches: [] };
      byRegency.set(c.regency_slug, regency);
    }
    regency.churches.push({ slug: c.slug, name: c.name, address: c.address });
  }
  return { name: rows[0].province_name, regencies: [...byRegency.values()] };
}

export async function getChurch(
  provinceSlug: string,
  regencySlug: string,
  churchSlug: string,
): Promise<Church | null> {
  return (
    (await all()).find(
      (c) =>
        c.province_slug === provinceSlug &&
        c.regency_slug === regencySlug &&
        c.slug === churchSlug,
    ) ?? null
  );
}

/** Every church, for generateStaticParams. */
export async function getChurchRoutes() {
  return (await all()).map((c) => ({
    province_slug: c.province_slug,
    regency_slug: c.regency_slug,
    slug: c.slug,
  }));
}

export async function getChurches() {
  return await all();
}
